/**
 * Verifies that [PersonalIdProfileBackupCodeFragment] branches on [EmailWorkFlow] rather than
 * pendingEmail.isNotEmpty(). The fixture uses FORGOT_BACKUP_CODE_EXISTING_USER workflow with a
 * non-empty pendingEmail, so the two conditions diverge and we can tell them apart.
 */
@Config(application = CommCareTestApplication::class)
@RunWith(AndroidJUnit4::class)
class PersonalIdProfileBackupCodeWorkflowBranchingTest : BasePersonalIdProfileTest() {
    private val fragmentArgs =
        PersonalIdProfileBackupCodeFragmentArgs
            .Builder()
            .setEmailWorkflow(EmailWorkFlow.FORGOT_BACKUP_CODE_EXISTING_USER)
            .setPendingEmail("grace@example.com")
            .build()
            .toBundle()

    @Before
    fun navigateToBackupCode() {
        PersonalIdUserPreferences.clearBackupCodeLockout()
        user.pin = "123456"
        onUiThread {
            navController.navigate(R.id.personalid_profile_backup_code_fragment, fragmentArgs)
        }
